-- mesh.lua
-- Generated by eilmer-mesher. Edit the .emesh.json project, not this file.
--   lmr prep-grids -j mesh.lua      registers the grids for a simulation
--   lmr custom-script -j mesh.lua   writes preview/blk-NNNN.vtk for the GUI
if config then config.dimensions = 2 end

-- points
p000 = Vector3:new{x=3.0, y=1.0}
p001 = Vector3:new{x=0.0, y=1.0}
p002 = Vector3:new{x=1.0, y=0.0}
p003 = Vector3:new{x=1.0, y=1.0}
p004 = Vector3:new{x=0.0, y=0.0}
p005 = Vector3:new{x=3.0, y=0.0}
p006 = Vector3:new{x=2.0, y=0.0}
p007 = Vector3:new{x=2.0, y=1.0}

-- paths
path_c3 = Line:new{p0=p000, p1=p001}
path_c5 = Line:new{p0=p002, p1=p003}
path_c1 = Line:new{p0=p004, p1=p005}
path_c4 = Line:new{p0=p001, p1=p004}
path_c6 = Line:new{p0=p006, p1=p007}
path_c2 = Line:new{p0=p005, p1=p000}

-- blocks
blocks = {}
-- block blk1
surf_blk1 = CoonsPatch:new{north=SubRangedPath:new{underlying_path=path_c3, t0=1.0, t1=0.6666666666666666}, east=path_c5, south=SubRangedPath:new{underlying_path=path_c1, t0=0.0, t1=0.3333333333333333}, west=ReversedPath:new{underlying_path=path_c4}}
grid_blk1 = StructuredGrid:new{psurface=surf_blk1, niv=11, njv=11, label="blk1"}
blocks[#blocks+1] = {grid=grid_blk1, tag="blk1", fsTag="initial", bcTags={west="inflow"}}

-- block blk2
surf_blk2 = CoonsPatch:new{north=SubRangedPath:new{underlying_path=path_c3, t0=0.6666666666666666, t1=0.3333333333333333}, east=path_c6, south=SubRangedPath:new{underlying_path=path_c1, t0=0.3333333333333333, t1=0.6666666666666666}, west=path_c5}
grid_blk2 = StructuredGrid:new{psurface=surf_blk2, niv=11, njv=11, label="blk2"}
blocks[#blocks+1] = {grid=grid_blk2, tag="blk2", fsTag="initial", bcTags={}}

-- block blk3
surf_blk3 = CoonsPatch:new{north=SubRangedPath:new{underlying_path=path_c3, t0=0.3333333333333333, t1=0.0}, east=path_c2, south=SubRangedPath:new{underlying_path=path_c1, t0=0.6666666666666666, t1=1.0}, west=path_c6}
grid_blk3 = StructuredGrid:new{psurface=surf_blk3, niv=11, njv=11, label="blk3"}
blocks[#blocks+1] = {grid=grid_blk3, tag="blk3", fsTag="initial", bcTags={east="outflow"}}

if registerFluidGrid then
   -- lmr prep-grids
   local ids = {}
   for i, b in ipairs(blocks) do
      ids[i] = registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   -- Blocks are joined only across block split lines; a solid curve between
   -- two blocks stays a wall on both sides.
   connectGrids(ids[1], "east", ids[2], "west")
   connectGrids(ids[2], "east", ids[3], "west")
else
   -- lmr custom-script: preview output for the GUI
   os.execute("mkdir -p preview")
   for i, b in ipairs(blocks) do
      b.grid:write_to_vtk_file(string.format("preview/blk-%04d.vtk", i-1))
   end
end
